using AutoMapper; using Health_Care_System.BLL.Interfaces; using Health_Care_System.PL.ViewModels; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace Health_Care_System.PL.Controllers;
[Authorize]
public class PatientsController:Controller { private const int PageSize=10; private readonly IPatientService _service; private readonly IMapper _mapper; public PatientsController(IPatientService service,IMapper mapper){_service=service;_mapper=mapper;}
public async Task<IActionResult> Index(string? searchValue,int pageIndex=1){var result=await _service.GetAllAsync(searchValue,pageIndex,PageSize);if(!result.Successeded||result.Data is null)return Problem(result.Error);var models=_mapper.Map<IEnumerable<PatientViewModel>>(result.Data);var page=Health_Care_System.BLL.Models.PaginatedList<PatientViewModel>.Create(models,result.Data.PageIndex,PageSize);ViewBag.SearchValue=searchValue;ViewBag.TotalCount=result.Data.TotalCount;return View(page);}
[HttpGet] public IActionResult Create()=>View(); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(PatientViewModel model){if(!ModelState.IsValid)return View(model);var entity=_mapper.Map<Health_Care_System.Entities.Patient>(model);var result=await _service.CreateAsync(entity);if(!result.Successeded){ModelState.AddModelError(string.Empty,result.Error!);return View(model);}return RedirectToAction(nameof(Index));}
public async Task<IActionResult> Details(int? id){if(id is null)return BadRequest();var result=await _service.GetByIdAsync(id.Value);if(!result.Successeded||result.Data is null)return NotFound();return View(_mapper.Map<PatientViewModel>(result.Data));}
[HttpGet] public async Task<IActionResult> Edit(int? id){if(id is null)return BadRequest();var result=await _service.GetByIdAsync(id.Value);if(!result.Successeded||result.Data is null)return NotFound();return View(_mapper.Map<PatientViewModel>(result.Data));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,PatientViewModel model){if(id!=model.Id)return BadRequest();if(!ModelState.IsValid)return View(model);var result=await _service.UpdateAsync(_mapper.Map<Health_Care_System.Entities.Patient>(model));if(!result.Successeded){ModelState.AddModelError(string.Empty,result.Error!);return View(model);}return RedirectToAction(nameof(Index));}
[HttpGet] public async Task<IActionResult> Delete(int? id){if(id is null)return BadRequest();var result=await _service.GetByIdAsync(id.Value);if(!result.Successeded||result.Data is null)return NotFound();return View(_mapper.Map<PatientViewModel>(result.Data));} [HttpPost,ActionName("Delete"),ValidateAntiForgeryToken] public async Task<IActionResult> ConfirmDelete(int id){var result=await _service.DeleteAsync(id);if(!result.Successeded)return NotFound();return RedirectToAction(nameof(Index));} }